'use strict';
function main(){
var n1=1.4,n2=1.9,th=53.5*Math.PI/180;
var s=n1*Math.sin(th)/n2;
var r=Math.asin(Math.min(1,s))*180/Math.PI;
return {n1:n1,n2:n2,incident_deg:53.5,refracted_deg:Math.round(r*100)/100};
}
try{var out=main();console.log(JSON.stringify(out));}catch(e){console.log(JSON.stringify({error:String(e&&e.message||e)}));process.exitCode=1;}

